resources/css/filament/app/theme.css — append a new block at the end of the file (after the topbar rule at :323-327):

  /* Chip colours. The panel's `primary` ramp is flat (#FF6666 at every shade 100-950),
     so any component pairing two primary shades renders one colour twice. Fixing the ramp
     would move buttons and links in both panels, so chips carry their own tokens here.
     Values are the shades Color::hex('#FF6666') generates. DEV-2557. */
  :root {
      --clarity-chip-bg: #FFE7E4;        /* primary-100 */
      --clarity-chip-text: #8C3132;      /* primary-800 — 6.82:1 on --clarity-chip-bg */
      --clarity-chip-bg-dark: rgb(240 103 101 / 0.18);   /* primary-500 @ 18% */
      --clarity-chip-text-dark: #FFCFCB; /* primary-200 */
  }

  /* `fi-select-input-value-badges-ctn` is created only by Filament's Select JS
     (vendor/filament/support/resources/js/utilities/select.js:824), and
     `fi-fo-tags-input-tags-ctn` only by tags-input.blade.php:101 — so this reaches every
     multi-value Select chip and every TagsInput tag in BOTH panels without touching table
     or status badges. The badge class string is hardcoded in that JS (select.js:751) and
     bypasses BadgeComponent::getColorMap(), so no ->color() API reaches it. */
  .fi-select-input-value-badges-ctn .fi-badge.fi-color-primary,
  .fi-fo-tags-input-tags-ctn .fi-badge.fi-color-primary {
      --text: var(--clarity-chip-text);
      --dark-text: var(--clarity-chip-text-dark);
      background-color: var(--clarity-chip-bg);
  }
  .fi-select-input-value-badges-ctn .fi-badge.fi-color-primary .fi-badge-delete-btn > .fi-icon,
  .fi-fo-tags-input-tags-ctn .fi-badge.fi-color-primary .fi-badge-delete-btn > .fi-icon {
      color: var(--clarity-chip-text);
  }
  .dark .fi-select-input-value-badges-ctn .fi-badge.fi-color-primary,
  .dark .fi-fo-tags-input-tags-ctn .fi-badge.fi-color-primary {
      background-color: var(--clarity-chip-bg-dark);
  }
  .dark .fi-select-input-value-badges-ctn .fi-badge.fi-color-primary .fi-badge-delete-btn > .fi-icon,
  .dark .fi-fo-tags-input-tags-ctn .fi-badge.fi-color-primary .fi-badge-delete-btn > .fi-icon {
      color: var(--clarity-chip-text-dark);
  }

  /* The Manage Zones ZIP chip and drawing banner are hand-rolled Tailwind, not Filament
     components, so the badge selectors above do not reach them. */
  .clarity-chip {
      background-color: var(--clarity-chip-bg);
      color: var(--clarity-chip-text);
  }
  .clarity-chip-btn { color: var(--clarity-chip-text); }
  .dark .clarity-chip {
      background-color: var(--clarity-chip-bg-dark);
      color: var(--clarity-chip-text-dark);
  }
  .dark .clarity-chip-btn { color: var(--clarity-chip-text-dark); }

